INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(25740, 0, 0, 'The Ice Stone has melted!', 12, 0, 100, 0, 0, 0, 'Ahune - SAY_PLAYER_TEXT_3'),
(25740, 1, 0, 'Ahune, your strength grows no more!', 12, 0, 100, 0, 0, 0, 'Ahune - SAY_PLAYER_TEXT_1'),
(25740, 2, 0, 'Your frozen reign will not come to pass!', 12, 0, 100, 0, 0, 0, 'Ahune - SAY_PLAYER_TEXT_2'),
(25740, 3, 0, 'The Earthen Ring\'s Assault Begins.', 41, 0, 100, 0, 0, 0, 'Ahune - EMOTE_EARTHEN_ASSAULT'),
(25740, 4, 0, 'Ahune Retreats.  His defenses diminish.', 41, 0, 100, 0, 0, 0, 'Ahune - EMOTE_SUBMERGED'),
(25740, 5, 0, 'Ahune will soon resurface.', 41, 0, 100, 0, 0, 0, 'Ahune - EMOTE_EMERGE_SOON');
