INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(20870, 0, 0, 'Life energy to... consume.', 14, 0, 100, 0, 0, 11250, 'Zereketh The Unbound - Aggro Say'),
(20870, 1, 0, 'This vessel is empty.', 14, 0, 100, 0, 0, 11251, 'Zereketh The Unbound - Player Death Say'),
(20870, 1, 1, 'No... more... life.', 14, 0, 100, 0, 0, 11252, 'Zereketh The Unbound - Player Death Say'),
(20870, 2, 0, 'The shadow... will engulf you.', 14, 0, 100, 0, 0, 11253, 'Zereketh The Unbound - Cast Shadow Nova Say'),
(20870, 2, 1, 'Darkness... consumes all.', 14, 0, 100, 0, 0, 11254, 'Zereketh The Unbound - Cast Shadow Nova Say'),
(20870, 3, 0, 'The Void... beckons.', 14, 0, 100, 0, 0, 11255, 'Zereketh The Unbound - On Death Say');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(20885, 0, 0, 'Don\'t worry about me; kill that worthless dullard instead!', 14, 0, 100, 1, 0, 11085, 'Dalliah the Doomsayer - Aggro Soccothrates First'),
(20885, 1, 0, 'It is unwise to anger me!', 14, 0, 100, 0, 0, 11086, 'Dalliah the Doomsayer - Aggro'),
(20885, 2, 0, 'Completely ineffective.  Just like someone else I know.', 14, 0, 100, 0, 0, 11087, 'Dalliah the Doomsayer - Kill'),
(20885, 2, 1, 'You chose the wrong opponent.', 14, 0, 100, 0, 0, 11088, 'Dalliah the Doomsayer - Kill'),
(20885, 3, 0, 'Reap the whirlwind!', 14, 0, 100, 0, 0, 11089, 'Dalliah the Doomsayer - Cast Whirlwind'),
(20885, 3, 1, 'I\'ll cut you to pieces!', 14, 0, 100, 0, 0, 11090, 'Dalliah the Doomsayer - Cast Whirlwind'),
(20885, 4, 0, 'That is much better.', 14, 0, 100, 0, 0, 11091, 'Dalliah the Doomsayer - Cast Heal'),
(20885, 4, 1, 'Ahh... just what I needed.', 14, 0, 100, 0, 0, 11092, 'Dalliah the Doomsayer - Cast Heal'),
(20885, 5, 0, 'Now I\'m really angry.', 14, 0, 100, 0, 0, 11093, 'Dalliah the Doomsayer - Death'),
(20885, 6, 0, 'More than you can handle, scryer?', 14, 0, 100, 1, 0, 11094, 'Dalliah the Doomsayer - Soccothrates at 25%'),
(20885, 6, 1, 'I suppose I\'ll end up fighting them all myself.', 14, 0, 100, 1, 0, 11095, 'Dalliah the Doomsayer - Soccothrates at 25%'),
(20885, 6, 2, 'I\'ve grown used to cleaning up your messes.', 14, 0, 100, 1, 0, 11096, 'Dalliah the Doomsayer - Soccothrates at 25%'),
(20885, 7, 0, 'Congratulations.  I\'ve wanted to do that for years.', 14, 0, 100, 66, 0, 11097, 'Dalliah the Doomsayer - Soccothratess dies'),
(20885, 8, 0, 'Why would I call on you?', 14, 0, 100, 396, 0, 0, 'Dalliah the Doomsayer - Conversation with Soccothrates part 1'),
(20885, 9, 0, 'When I need someone to prance around like an overstuffed peacock, I\'ll call on you.', 14, 0, 100, 396, 0, 0, 'Dalliah the Doomsayer - Conversation with Soccothrates part 2'),
(20885, 10, 0, 'What would you know about commitment, sheet-sah?', 14, 0, 100, 396, 0, 0, 'Dalliah the Doomsayer - Conversation with Soccothrates part 3');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(20886, 0, 0, 'Have you come to kill Dalliah?  Can I watch?', 14, 0, 100, 1, 0, 11237, 'Wrath-Scryer Soccothrates - Aggro Dalliah First'),
(20886, 1, 0, 'At last, a target for my frustrations!', 14, 0, 100, 0, 0, 11238, 'Wrath-Scryer Soccothrates - Aggro'),
(20886, 2, 0, 'Yes, that was quite satisfying.', 14, 0, 100, 0, 0, 11239, 'Wrath-Scryer Soccothrates - Kill'),
(20886, 3, 0, 'On guard!', 14, 0, 100, 0, 0, 11241, 'Wrath-Scryer Soccothrates - Knock Away'),
(20886, 3, 1, 'Defend yourself, for all the good it will do....', 14, 0, 100, 0, 0, 11242, 'Wrath-Scryer Soccothrates - Knock Away'),
(20886, 4, 0, 'Knew this was... the only way out.', 14, 0, 100, 0, 0, 11243, 'Wrath-Scryer Soccothrates - Death'),
(20886, 5, 0, 'Having problems, Dalliah?  How nice.', 14, 0, 100, 1, 0, 11244, 'Wrath-Scryer Soccothrates - Dalliah at 25%'),
(20886, 5, 1, 'This may be the end for you, Dalliah.  What a shame that would be.', 14, 0, 100, 1, 0, 11245, 'Wrath-Scryer Soccothrates - Dalliah at 25%'),
(20886, 5, 2, 'I suggest a new strategy: you draw their attacks while I gather reinforcements.', 14, 0, 100, 1, 0, 11246, 'Wrath-Scryer Soccothrates - Dalliah at 25%'),
(20886, 6, 0, 'Finally!  Well done!', 14, 0, 100, 66, 0, 11247, 'Wrath-Scryer Soccothrates - Dalliah dies'),
(20886, 7, 0, 'Did you call on me?', 14, 0, 100, 397, 0, 11236, 'Wrath-Scryer Soccothrates - Conversation with Dalliah part 1'),
(20886, 8, 0, 'To do your heavy lifting, most likely.', 14, 0, 100, 396, 0, 0, 'Wrath-Scryer Soccothrates - Conversation with Dalliah part 2'),
(20886, 9, 0, 'Then I\'ll commit myself to ignoring you.', 14, 0, 100, 396, 0, 0, 'Wrath-Scryer Soccothrates - Conversation with Dalliah part 3'),
(20886, 10, 0, 'You\'re the one who should be-- Wait, we have company...', 14, 0, 100, 396, 0, 0, 'Wrath-Scryer Soccothrates - Conversation with Dalliah part 4');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(20904, 0, 0, 'I knew the prince would be angry, but I... I have not been myself. I had to let them out! The great one speaks to me, you see. Wait--outsiders. Kael\'thas did not send you! Good... I\'ll just tell the prince you released the prisoners!', 14, 0, 100, 0, 0, 11222, 'Warden Mellichar'),
(20904, 1, 0, 'The naaru kept some of the most dangerous beings in existence here in these cells. Let me introduce you to another....', 14, 0, 100, 0, 0, 11223, 'Warden Mellichar'),
(20904, 2, 0, 'Yes, yes... another! Your will is mine!', 14, 0, 100, 0, 0, 11224, 'Warden Mellichar'),
(20904, 3, 0, 'Behold, yet another terrifying creature of incomprehensible power!', 14, 0, 100, 0, 0, 11225, 'Warden Mellichar'),
(20904, 4, 0, 'What is this? A lowly gnome? I will do better, oh great one.', 14, 0, 100, 0, 0, 11226, 'Warden Mellichar'),
(20904, 5, 0, 'Anarchy! Bedlam! Oh, you are so wise! Yes, I see it now, of course!', 14, 0, 100, 0, 0, 11227, 'Warden Mellichar'),
(20904, 6, 0, 'One final cell remains. Yes, O great one, right away!', 14, 0, 100, 0, 0, 11228, 'Warden Mellichar'),
(20904, 7, 0, 'Welcome, O great one. I am your humble servant.', 14, 0, 100, 0, 0, 11229, 'Warden Mellichar');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(20912, 0, 0, 'It is a small matter to control the mind of the weak... for I bear allegiance to powers untouched by time, unmoved by fate. No force on this world or beyond harbors the strength to bend our knee... not even the mighty Legion! ', 14, 0, 100, 0, 0, 11122, 'skyriss SAY_INTRO'),
(20912, 1, 0, 'Bear witness to the agent of your demise!', 14, 0, 100, 0, 0, 11123, 'skyriss SAY_AGGRO'),
(20912, 2, 0, 'Your fate is written.', 14, 0, 100, 0, 0, 11124, 'skyriss SAY_KILL_1'),
(20912, 2, 1, 'The chaos I have sown here is but a taste....', 14, 0, 100, 0, 0, 11125, 'skyriss SAY_KILL_2'),
(20912, 3, 0, 'You will do my bidding, weakling.', 14, 0, 100, 0, 0, 11127, 'skyriss SAY_MIND_1'),
(20912, 3, 1, 'Your will is no longer your own.', 14, 0, 100, 0, 0, 11128, 'skyriss SAY_MIND_2'),
(20912, 4, 0, 'Flee in terror.', 14, 0, 100, 0, 0, 11129, 'skyriss SAY_FEAR_1'),
(20912, 4, 1, 'I will show you horrors undreamed of.', 14, 0, 100, 0, 0, 11130, 'skyriss SAY_FEAR_2'),
(20912, 5, 0, 'We span the universe, as countless as the stars!', 14, 0, 100, 0, 0, 11131, 'skyriss SAY_IMAGE'),
(20912, 6, 0, 'I am merely one of... infinite multitudes.', 14, 0, 100, 0, 0, 11126, 'skyriss SAY_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(20977, 0, 0, 'Where in Bonzo\'s Brass Buttons am I? And who are-- yaaghh, that\'s one mother of a headache!', 14, 0, 100, 0, 0, 11171, 'Millhouse Manastorm'),
(20977, 1, 0, '\"Lowly\"? I don\'t care who you are, friend: no one refers to the mighty Millhouse Manastorm as \"lowly\"!', 14, 0, 100, 0, 0, 11172, 'Millhouse Manastorm'),
(20977, 2, 0, 'I just need to get some things ready first. You guys go ahead and get started. I need to summon up some water....', 14, 0, 100, 0, 0, 11173, 'Millhouse Manastorm'),
(20977, 3, 0, 'Fantastic! Next, some protective spells. Yeah, now we\'re cookin\'!', 14, 0, 100, 0, 0, 11174, 'Millhouse Manastorm'),
(20977, 4, 0, 'And of course I\'ll need some mana. You guys are gonna love this; just wait....', 14, 0, 100, 0, 0, 11175, 'Millhouse Manastorm'),
(20977, 5, 0, 'Aaalllriiiight!! Who ordered up an extra large can of whoop-ass?', 14, 0, 100, 0, 0, 11176, 'Millhouse Manastorm'),
(20977, 6, 0, 'I didn\'t even break a sweat on that one!', 14, 0, 100, 0, 0, 11177, 'Millhouse Manastorm'),
(20977, 6, 1, 'You guys feel free to jump in anytime.', 14, 0, 100, 0, 0, 11178, 'Millhouse Manastorm'),
(20977, 7, 0, 'I\'m gonna light you up, sweet cheeks!', 14, 0, 100, 0, 0, 11179, 'Millhouse Manastorm'),
(20977, 8, 0, 'Ice, ice baby.', 14, 0, 100, 0, 0, 11180, 'Millhouse Manastorm'),
(20977, 9, 0, 'Heal me! For the love of all that\'s holy, heal me! I\'m dying!!', 14, 0, 100, 0, 0, 11181, 'Millhouse Manastorm'),
(20977, 10, 0, 'You\'ll be hearing from my lawyer!', 14, 0, 100, 0, 0, 11182, 'Millhouse Manastorm'),
(20977, 11, 0, 'Who\'s bad? Who\'s bad? That\'s right: we bad!', 14, 0, 100, 0, 0, 11183, 'Millhouse Manastorm');
